301	        }),
302	      );
303	      return response;
304	    },
305	    initialPageParam: "",
306	    getNextPageParam: (lastPage) => lastPage.nextPageToken || undefined,
307	    select: (data) => data.pages.flatMap((page) => page.memos),
308	    enabled: options?.enabled ?? true,
309	    staleTime: 1000 * 60, // 1 minute
310	  });
311	}
